  4	public class Trie {
  5	    private static final int ALPHABET_SIZE = 26;
  6	    private static final String[] WORDS = {"and", "ant", "do", "dad"};
  7	    private static final String[] SEARCH_KEYS = {"do", "gee", "bat"};
  8	    private static final String[] PREFIX_KEYS = {"ge", "ba", "do", "de"};
  9	
 10	    private static final class TrieNode {
 11	        private final TrieNode[] children = new TrieNode[ALPHABET_SIZE];
 12	        private boolean isLeaf;
 13	
 14	        private TrieNode childAt(int index) {
 15	            return children[index];
 16	        }
 17	
 18	        private TrieNode ensureChild(int index) {
 19	            if (children[index] == null) {
 20	                children[index] = new TrieNode();
 21	            }
 22	            return children[index];
 23	        }
 24	
 25	        private void markAsLeaf() {
 26	            isLeaf = true;
 27	        }
 28	
 29	        private boolean isLeaf() {
 30	            return isLeaf;
 31	        }
 32	    }
 33	
 34	    private enum TraversalMode {
 35	        CREATE_MISSING {
 36	            @Override
 37	            TrieNode next(TrieNode node, int index) {
 38	                return node.ensureChild(index);
 39	            }
 40	        },
 41	        EXISTING_ONLY {
 42	            @Override
 43	            TrieNode next(TrieNode node, int index) {
 44	                return node.childAt(index);
 45	            }
 46	        };
 47	
 48	        abstract TrieNode next(TrieNode node, int index);
 49	    }
 50	
 51	    private final TrieNode root = new TrieNode();
 52	
 53	    public void insert(String key) {
 54	        TrieNode node = ensurePath(key);
 55	        node.markAsLeaf();
 56	    }
 57	
 58	    public void insertAll(String... keys) {
 59	        for (String key : keys) {
 60	            insert(key);
 61	        }
 62	    }
 63	
 64	    public boolean search(String key) {
 65	        TrieNode node = findNode(key);
 66	        return node != null && node.isLeaf();
 67	    }
 68	
 69	    public boolean isPrefix(String prefix) {
 70	        return findNode(prefix) != null;
 71	    }
 72	
 73	    private TrieNode ensurePath(String key) {
 74	        return walk(key, TraversalMode.CREATE_MISSING);
 75	    }
 76	
 77	    private TrieNode findNode(String key) {
 78	        return walk(key, TraversalMode.EXISTING_ONLY);
 79	    }
