 81	    private TrieNode walk(String key, TraversalMode mode) {
 82	        Objects.requireNonNull(key, "key");
 83	        TrieNode node = root;
 84	        for (int i = 0; i < key.length(); i++) {
 85	            int index = toIndex(key.charAt(i), key);
 86	            node = mode.next(node, index);
 87	            if (node == null) {
 88	                return null;
 89	            }
 90	        }
 91	        return node;
 92	    }
 93	
 94	    private static int toIndex(char c, String key) {
 95	        if (c < 'a' || c > 'z') {
 96	            throw new IllegalArgumentException(
 97	                "Keys must contain only lowercase letters a-z: " + key);
 98	        }
 99	        return c - 'a';
100	    }
